import adsk.core
import adsk.fusion
import adsk.cam
import traceback
import math


# Fusion 360 Parametric Microgreens Humidity Dome Generator
#
# Creates a one-piece humidity dome sized to sit on the water tray generated by
# microgreen_trays.py. Because that tray already uses nearly the full X1C bed,
# this dome matches the tray outer footprint and rests on the tray rim rather
# than wrapping around the tray exterior.


# =========================
# PARAMETERS - EDIT THESE
# =========================

# Keep these in sync with microgreen_trays.py so the dome matches the tray.
WATER_TRAY_OUTER_WIDTH_MM = 248.0
WATER_TRAY_OUTER_DEPTH_MM = 248.0

# X1C bed constraints.
X1C_BED_WIDTH_MM = 256.0
X1C_BED_DEPTH_MM = 256.0
X1C_EDGE_CLEARANCE_MM = 2.0
X1C_BOTTOM_LEFT_EXCLUSION_WIDTH_MM = 18.0
X1C_BOTTOM_LEFT_EXCLUSION_DEPTH_MM = 18.0

# Dome body.
DOME_HEIGHT_MM = 95.0
DOME_WALL_THICKNESS_MM = 2.4
DOME_TOP_THICKNESS_MM = 2.4

# Bottom seating relief.
# This small chamfer reduces the sharp inside edge so the dome drops onto the
# tray rim more easily, but it does not create an outside wraparound skirt.
ADD_BOTTOM_LEAD_IN = True
BOTTOM_LEAD_IN_HEIGHT_MM = 3.0

# Corners.
OUTER_CORNER_RADIUS_MM = 10.0
INNER_CORNER_RADIUS_MM = 7.6

# Top vent holes.
ADD_TOP_VENT_HOLES = True
VENT_HOLE_DIAMETER_MM = 8.0
VENT_HOLE_ROWS = 2
VENT_HOLE_COLUMNS = 4
VENT_HOLE_SPACING_MM = 26.0

# Workspace placement.
X_OFFSET_MM = 500.0

# Optional text on top.
ADD_TOP_LABEL = True
TOP_LABEL_TEXT = "DOME"
TEXT_HEIGHT_MM = 12.0
TEXT_DEPTH_MM = 0.6


def mm(value):
    return value / 10.0  # Fusion API internal unit is cm


def fit_to_x1c_reachable_area_mm(requested_width_mm, requested_depth_mm):
    """Fits a rectangle to X1C reachable area with an optional bottom-left exclusion zone."""
    bed_w = max(1.0, X1C_BED_WIDTH_MM - 2.0 * X1C_EDGE_CLEARANCE_MM)
    bed_d = max(1.0, X1C_BED_DEPTH_MM - 2.0 * X1C_EDGE_CLEARANCE_MM)

    fit_w = min(requested_width_mm, bed_w)
    fit_d = min(requested_depth_mm, bed_d)
    adjusted = (fit_w != requested_width_mm) or (fit_d != requested_depth_mm)

    excl_w = max(0.0, X1C_BOTTOM_LEFT_EXCLUSION_WIDTH_MM)
    excl_d = max(0.0, X1C_BOTTOM_LEFT_EXCLUSION_DEPTH_MM)

    if excl_w <= 0.0 or excl_d <= 0.0:
        return fit_w, fit_d, adjusted

    can_shift_x = (bed_w - fit_w) >= excl_w
    can_shift_y = (bed_d - fit_d) >= excl_d
    if can_shift_x or can_shift_y:
        return fit_w, fit_d, adjusted

    target_w = max(1.0, bed_w - excl_w)
    target_d = max(1.0, bed_d - excl_d)
    reduce_w = max(0.0, fit_w - target_w)
    reduce_d = max(0.0, fit_d - target_d)

    if reduce_w <= reduce_d:
        fit_w = target_w
    else:
        fit_d = target_d

    return fit_w, fit_d, True


def create_centered_rounded_rect(sketch, width_mm, depth_mm, radius_mm, center_x_mm=0.0):
    """Creates a centered rounded rectangle profile using lines and arcs."""
    lines = sketch.sketchCurves.sketchLines
    arcs = sketch.sketchCurves.sketchArcs

    w = mm(width_mm)
    d = mm(depth_mm)
    r = mm(radius_mm)

    cx = mm(center_x_mm)
    x = w / 2.0
    y = d / 2.0

    p1 = adsk.core.Point3D.create(cx - x + r, -y, 0)
    p2 = adsk.core.Point3D.create(cx + x - r, -y, 0)
    p3 = adsk.core.Point3D.create(cx + x, -y + r, 0)
    p4 = adsk.core.Point3D.create(cx + x, y - r, 0)
    p5 = adsk.core.Point3D.create(cx + x - r, y, 0)
    p6 = adsk.core.Point3D.create(cx - x + r, y, 0)
    p7 = adsk.core.Point3D.create(cx - x, y - r, 0)
    p8 = adsk.core.Point3D.create(cx - x, -y + r, 0)

    lines.addByTwoPoints(p1, p2)
    arcs.addByCenterStartSweep(
        adsk.core.Point3D.create(cx + x - r, -y + r, 0),
        p2,
        math.radians(90)
    )
    lines.addByTwoPoints(p3, p4)
    arcs.addByCenterStartSweep(
        adsk.core.Point3D.create(cx + x - r, y - r, 0),
        p4,
        math.radians(90)
    )
    lines.addByTwoPoints(p5, p6)
    arcs.addByCenterStartSweep(
        adsk.core.Point3D.create(cx - x + r, y - r, 0),
        p6,
        math.radians(90)
    )
    lines.addByTwoPoints(p7, p8)
    arcs.addByCenterStartSweep(
        adsk.core.Point3D.create(cx - x + r, -y + r, 0),
        p8,
        math.radians(90)
    )


def extrude_profile(root_comp, profile, distance_mm, operation):
    extrudes = root_comp.features.extrudeFeatures
    ext_input = extrudes.createInput(profile, operation)
    ext_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(distance_mm)))
    return extrudes.add(ext_input)


def create_component(root_comp, name, x_offset_mm):
    comp = None
    origin_x_mm = 0.0

    try:
        occs = root_comp.occurrences
        matrix = adsk.core.Matrix3D.create()
        matrix.translation = adsk.core.Vector3D.create(mm(x_offset_mm), 0, 0)
        occ = occs.addNewComponent(matrix)
        comp = occ.component
        comp.name = name
    except RuntimeError:
        comp = root_comp
        origin_x_mm = x_offset_mm

    return comp, origin_x_mm


def create_humidity_dome(root_comp, name, x_offset_mm, width_mm, depth_mm, height_mm, wall_mm, top_mm):
    comp, origin_x_mm = create_component(root_comp, name, x_offset_mm)
    xy = comp.xYConstructionPlane

    outer_sketch = comp.sketches.add(xy)
    outer_sketch.name = f"{name} outer footprint"
    create_centered_rounded_rect(outer_sketch, width_mm, depth_mm, OUTER_CORNER_RADIUS_MM, origin_x_mm)
    outer_body = extrude_profile(comp, outer_sketch.profiles.item(0), height_mm, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    outer_body.bodies.item(0).name = name

    inner_width = width_mm - 2.0 * wall_mm
    inner_depth = depth_mm - 2.0 * wall_mm
    if inner_width <= 0 or inner_depth <= 0:
        raise ValueError("Dome inner opening is invalid. Reduce wall thickness or increase footprint.")

    inner_sketch = comp.sketches.add(xy)
    inner_sketch.name = f"{name} inner hollow cut"
    create_centered_rounded_rect(inner_sketch, inner_width, inner_depth, INNER_CORNER_RADIUS_MM, origin_x_mm)

    cut_distance = height_mm - top_mm
    if cut_distance <= 0:
        raise ValueError("Dome top thickness must be smaller than total dome height.")

    cut_input = comp.features.extrudeFeatures.createInput(
        inner_sketch.profiles.item(0),
        adsk.fusion.FeatureOperations.CutFeatureOperation
    )
    cut_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(cut_distance)))
    comp.features.extrudeFeatures.add(cut_input)

    return comp, origin_x_mm, inner_width, inner_depth


def add_bottom_lead_in(comp, width_mm, depth_mm, origin_x_mm=0.0):
    if not ADD_BOTTOM_LEAD_IN or BOTTOM_LEAD_IN_HEIGHT_MM <= 0:
        return

    xy = comp.xYConstructionPlane
    sketch = comp.sketches.add(xy)
    sketch.name = "bottom lead-in cut"

    relief_width = width_mm - 2.0 * max(0.0, DOME_WALL_THICKNESS_MM - 0.8)
    relief_depth = depth_mm - 2.0 * max(0.0, DOME_WALL_THICKNESS_MM - 0.8)
    relief_radius = max(0.8, INNER_CORNER_RADIUS_MM + 0.8)
    create_centered_rounded_rect(sketch, relief_width, relief_depth, relief_radius, origin_x_mm)

    cut_input = comp.features.extrudeFeatures.createInput(
        sketch.profiles.item(0),
        adsk.fusion.FeatureOperations.CutFeatureOperation
    )
    cut_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(BOTTOM_LEAD_IN_HEIGHT_MM)))
    comp.features.extrudeFeatures.add(cut_input)


def add_top_vent_holes(comp, width_mm, depth_mm, height_mm, top_mm, origin_x_mm=0.0):
    if not ADD_TOP_VENT_HOLES:
        return

    if VENT_HOLE_ROWS <= 0 or VENT_HOLE_COLUMNS <= 0:
        return

    xy = comp.xYConstructionPlane
    plane_input = comp.constructionPlanes.createInput()
    plane_input.setByOffset(xy, adsk.core.ValueInput.createByReal(mm(height_mm)))
    top_plane = comp.constructionPlanes.add(plane_input)

    sketch = comp.sketches.add(top_plane)
    sketch.name = "top vent holes"

    circles = sketch.sketchCurves.sketchCircles
    radius = mm(VENT_HOLE_DIAMETER_MM / 2.0)

    max_pattern_w = max(0.0, width_mm - 40.0)
    max_pattern_d = max(0.0, depth_mm - 40.0)
    pattern_w = min(max_pattern_w, (VENT_HOLE_COLUMNS - 1) * VENT_HOLE_SPACING_MM)
    pattern_d = min(max_pattern_d, (VENT_HOLE_ROWS - 1) * VENT_HOLE_SPACING_MM)

    start_x = -pattern_w / 2.0
    start_y = -pattern_d / 2.0

    for row in range(VENT_HOLE_ROWS):
        for col in range(VENT_HOLE_COLUMNS):
            x = start_x + col * VENT_HOLE_SPACING_MM
            y = start_y + row * VENT_HOLE_SPACING_MM
            circles.addByCenterRadius(adsk.core.Point3D.create(mm(origin_x_mm + x), mm(y), 0), radius)

    profiles = adsk.core.ObjectCollection.create()
    for profile in sketch.profiles:
        profiles.add(profile)

    if profiles.count == 0:
        return

    cut_input = comp.features.extrudeFeatures.createInput(profiles, adsk.fusion.FeatureOperations.CutFeatureOperation)
    cut_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(-(top_mm + 0.5))))
    comp.features.extrudeFeatures.add(cut_input)


def add_top_label(comp, label, width_mm, depth_mm, height_mm, origin_x_mm=0.0):
    if not ADD_TOP_LABEL or not label:
        return

    xy = comp.xYConstructionPlane
    plane_input = comp.constructionPlanes.createInput()
    plane_input.setByOffset(xy, adsk.core.ValueInput.createByReal(mm(height_mm)))
    top_plane = comp.constructionPlanes.add(plane_input)

    sketch = comp.sketches.add(top_plane)
    sketch.name = f"{label} top label"

    try:
        text_input = sketch.sketchTexts.createInput2(label, mm(TEXT_HEIGHT_MM))
        text_input.setAsMultiLine(
            adsk.core.Point3D.create(mm(origin_x_mm - width_mm / 4.0), mm(-depth_mm / 8.0), 0),
            adsk.core.Point3D.create(mm(origin_x_mm + width_mm / 4.0), mm(depth_mm / 8.0), 0),
            adsk.core.HorizontalAlignments.CenterHorizontalAlignment,
            adsk.core.VerticalAlignments.MiddleVerticalAlignment,
            0
        )
        sketch.sketchTexts.add(text_input)

        profiles = adsk.core.ObjectCollection.create()
        for profile in sketch.profiles:
            profiles.add(profile)

        if profiles.count > 0:
            ext_input = comp.features.extrudeFeatures.createInput(profiles, adsk.fusion.FeatureOperations.JoinFeatureOperation)
            ext_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(TEXT_DEPTH_MM)))
            comp.features.extrudeFeatures.add(ext_input)
    except:
        pass


def run(context):
    ui = None
    try:
        app = adsk.core.Application.get()
        ui = app.userInterface
        design = app.activeProduct

        if not isinstance(design, adsk.fusion.Design):
            ui.messageBox("Please open a Fusion 360 design before running this script.")
            return

        root = design.rootComponent

        dome_width_mm, dome_depth_mm, was_adjusted = fit_to_x1c_reachable_area_mm(
            WATER_TRAY_OUTER_WIDTH_MM,
            WATER_TRAY_OUTER_DEPTH_MM,
        )

        dome, origin_x_mm, inner_width_mm, inner_depth_mm = create_humidity_dome(
            root,
            "Microgreens Humidity Dome",
            X_OFFSET_MM,
            dome_width_mm,
            dome_depth_mm,
            DOME_HEIGHT_MM,
            DOME_WALL_THICKNESS_MM,
            DOME_TOP_THICKNESS_MM,
        )

        add_bottom_lead_in(dome, dome_width_mm, dome_depth_mm, origin_x_mm)
        add_top_vent_holes(dome, dome_width_mm, dome_depth_mm, DOME_HEIGHT_MM, DOME_TOP_THICKNESS_MM, origin_x_mm)
        add_top_label(dome, TOP_LABEL_TEXT, inner_width_mm, inner_depth_mm, DOME_HEIGHT_MM, origin_x_mm)

        message = (
            "Humidity dome created.\n\n"
            f"Outer footprint: {dome_width_mm:.1f} x {dome_depth_mm:.1f} mm\n"
            f"Interior clearance: {inner_width_mm:.1f} x {inner_depth_mm:.1f} x {DOME_HEIGHT_MM - DOME_TOP_THICKNESS_MM:.1f} mm\n\n"
            "Print recommendation: place the closed top face on the build plate so the dome prints open-side up without supports."
        )

        if was_adjusted:
            message += (
                "\n\n"
                "The dome footprint was reduced to match the X1C reachable area. "
                "If you also adjusted the tray script, keep the water tray dimensions in both scripts aligned."
            )

        ui.messageBox(message)

    except Exception:
        if ui:
            ui.messageBox("Failed:\n{}".format(traceback.format_exc()))